// SMAC Draft Loader (Fase 5)
// Preloads a draft generated by the SMAC agent (?draft=<id>) into the
// creation form. Read-only: never starts a simulation on its own.
const DraftLoader = (function () {
    let currentDraft = null;
    let currentParent = null;
    let parentPaused = false;

    function getDraftId() {
        try {
            return new URLSearchParams(window.location.search).get("draft");
        } catch (e) {
            return null;
        }
    }

    function init() {
        const draftId = getDraftId();
        if (!draftId) return;
        setupButtons();
        // Deferred: ScenarioManager.initializeScenarios() must have run first.
        setTimeout(() => loadDraft(draftId), 0);
    }

    function setupButtons() {
        const discard = document.getElementById("smac-draft-discard");
        if (discard) {
            discard.addEventListener("click", () => {
                const url = new URL(window.location.href);
                url.searchParams.delete("draft");
                window.location.href = url.toString();
            });
        }
        const stopParent = document.getElementById("smac-draft-stop-parent");
        if (stopParent) {
            stopParent.addEventListener("click", () => {
                if (!currentParent) return;
                const typed = window.prompt(
                    "Para detener la simulación original, escribe su nombre:\n\n" + currentParent);
                if (typed === null) return;
                // Reinforced confirmation: the backend requires the typed name.
                fetch("/platform/smac/chat/", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        message: "detener la simulación original",
                        scenario: currentParent,
                    }),
                }).catch(() => {});
                fetch("/platform/smac/propose", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        kind: "stop_scenario", scenario: currentParent,
                        params: {}, description: "Detener la simulación original",
                    }),
                })
                    .then(r => r.json())
                    .then(rec => {
                        if (!rec || !rec.id) return;
                        return fetch("/platform/smac/chat/confirm", {
                            method: "POST",
                            headers: { "Content-Type": "application/json" },
                            body: JSON.stringify({ id: rec.id, confirm: true, confirm_name: typed }),
                        });
                    })
                    .then(r => (r && r.json ? r.json() : null))
                    .then(res => {
                        if (res && res.ok) {
                            stopParent.style.display = "none";
                            parentPaused = false;
                        } else {
                            window.alert((res && res.detail) || "No se pudo detener la simulación original.");
                        }
                    })
                    .catch(() => window.alert("No se pudo detener la simulación original."));
            });
        }
    }

    function loadDraft(draftId) {
        fetch("/platform/smac/draft/" + encodeURIComponent(draftId))
            .then(async (response) => {
                if (!response.ok) {
                    let detail = "No se pudo cargar el borrador.";
                    try {
                        const body = await response.json();
                        detail = body.detail || body.error || detail;
                    } catch (e) { /* ignore */ }
                    showError(detail);
                    return null;
                }
                return response.json();
            })
            .then((draft) => {
                if (!draft) return;
                applyDraft(draft);
            })
            .catch(() => showError("No se pudo cargar el borrador."));
    }

    function applyDraft(draft) {
        currentDraft = draft;
        currentParent = draft.parent || (draft.derived_from && draft.derived_from.scenario) || null;

        // Pre-generate the topology from topology_hint BEFORE loading the draft,
        // so setScenariosList's loadScenarioData() keeps the regenerated graph.
        if (draft.topology_hint) {
            const sel = document.getElementById("predefined-topology-select");
            const nodes = document.getElementById("predefined-topology-nodes");
            if (sel && draft.topology_hint.type) sel.value = draft.topology_hint.type;
            if (nodes && draft.topology_hint.n_nodes != null) nodes.value = draft.topology_hint.n_nodes;
        }

        if (window.ScenarioManager) {
            window.ScenarioManager.setScenariosList([draft]);
            window.ScenarioManager.saveScenario();
        }
        renderBanner(draft);
    }

    function changeLabel(kind, value) {
        const labels = {
            federation: "Federación", topology: "Topología", nodes: "Nº de nodos",
            model: "Modelo", batch_size: "batch_size", policy: "Política SA",
            rounds: "Rondas", epochs: "Epochs",
        };
        return (labels[kind] || kind) + ": " + value;
    }

    function renderBanner(draft) {
        const banner = document.getElementById("smac-draft-banner");
        if (!banner) return;
        const title = document.getElementById("smac-draft-title");
        const changesEl = document.getElementById("smac-draft-changes");
        const noteEl = document.getElementById("smac-draft-note");

        const parent = draft.parent || (draft.derived_from && draft.derived_from.scenario) || "?";
        const roundNo = draft.derived_from ? draft.derived_from.round : null;
        if (title) {
            title.textContent = "Borrador generado por SMAC a partir de " + parent +
                (roundNo != null ? " (ronda " + roundNo + ")" : "");
        }
        if (changesEl) {
            changesEl.textContent = "";
            const changes = (draft.derived_from && draft.derived_from.changes) || {};
            Object.keys(changes).forEach((kind) => {
                const change = changes[kind];
                if (typeof change !== "object") return;
                const from = change.from_federation || change.from_topology ||
                    change.from_model || change.from_n_nodes || (change.kind === kind ? "" : "");
                const to = change.to_federation || change.to_topology ||
                    change.to_model || change.n_nodes || change.sar_neighbor_policy ||
                    change.batch_size || change.total_rounds || change.epochs || "";
                const line = document.createElement("div");
                line.textContent = "→ " + changeLabel(kind, to != null ? to : JSON.stringify(change));
                changesEl.appendChild(line);
            });
        }
        if (noteEl) {
            let note = "Esta simulación empezará desde cero. Revisa y pulsa el botón de iniciar.";
            if (draft.lost_node_attributes && draft.lost_node_attributes.length) {
                note += " Atributos por nodo que se pierden al re-topologizar: " +
                    draft.lost_node_attributes.join(", ") + ".";
            }
            noteEl.textContent = note;
        }
        banner.style.display = "block";
    }

    function showError(detail) {
        const banner = document.getElementById("smac-draft-banner");
        if (!banner) return;
        const title = document.getElementById("smac-draft-title");
        const noteEl = document.getElementById("smac-draft-note");
        if (title) title.textContent = "Borrador no disponible";
        if (noteEl) noteEl.textContent = detail || "El borrador expiró o no existe. Puedes crear la simulación manualmente.";
        banner.style.display = "block";
        const discard = document.getElementById("smac-draft-discard");
        if (discard) discard.style.display = "";
    }

    function setParentPaused(paused) {
        parentPaused = paused;
        const stopParent = document.getElementById("smac-draft-stop-parent");
        if (stopParent) stopParent.style.display = paused ? "" : "none";
    }

    return { init, applyDraft, renderBanner, getDraftId, setParentPaused };
})();

export default DraftLoader;
